// The opening bracket that `c` closes, or no value if `c` isn't a closing bracket.
[[nodiscard]] constexpr std::optional<char> opener_of(char c) {
  switch (c) {
    case ')': return '(';
    case ']': return '[';
    case '}': return '{';
    default: return std::nullopt;
  }
}

[[nodiscard]] bool is_balanced(std::string_view s) {
  std::vector<char> open;  // brackets still waiting to be closed, the most recent at the back
  for (const char c : s) {
    if (c == '(' || c == '[' || c == '{') {
      open.push_back(c);
    } else if (const std::optional<char> opener = opener_of(c)) {
      if (open.empty() || open.back() != *opener) return false;
      open.pop_back();
    }
  }
  return open.empty();
}

int main() {
  for (const std::string_view s : {"([]{})", "f(a[i]) { return; }", "([)]", "((", ")(", ""})
    std::cout << std::format("{:<24}{}\n", std::format("\"{}\"", s), is_balanced(s));
}

