struct Tally {
  std::int64_t bytes = 0;
  std::int64_t allocations = 0;
};

template <typename T>
struct Counting {
  using value_type = T;
  Tally* tally;
  explicit Counting(Tally* t) : tally(t) {}
  template <typename U>
  Counting(const Counting<U>& other) : tally(other.tally) {}  // a container may allocate other types too
  [[nodiscard]] T* allocate(std::size_t n) {
    tally->bytes += static_cast<std::int64_t>(n * sizeof(T));
    ++tally->allocations;
    return std::allocator<T>{}.allocate(n);
  }
  void deallocate(T* p, std::size_t n) { std::allocator<T>{}.deallocate(p, n); }
  template <typename U>
  bool operator==(const Counting<U>& other) const { return tally == other.tally; }
};

template <typename Container>
void measure(std::string_view name) {
  Tally tally;
  std::stack<int, Container> stack(Counting<int>{&tally});
  std::cout << std::format("{}: {} bytes in {} allocations while empty", name, tally.bytes, tally.allocations);
  for (int i = 0; i < 1000; ++i) stack.push(i);
  std::cout << std::format(", {} bytes in {} after 1000 pushes\n", tally.bytes, tally.allocations);
}

int main() {
  measure<std::deque<int, Counting<int>>>("stack on deque");
  measure<std::vector<int, Counting<int>>>("stack on vector");
}

