// For each reading, how many steps later the next higher reading comes, or no value if none does.
[[nodiscard]] std::vector<std::optional<std::ptrdiff_t>> steps_to_higher(std::span<const int> readings) {
  std::vector<std::optional<std::ptrdiff_t>> steps(readings.size());
  std::vector<std::ptrdiff_t> waiting;  // indices; their readings never increase towards the back
  for (std::ptrdiff_t i = 0; i < std::ssize(readings); ++i) {
    while (!waiting.empty() && readings[waiting.back()] < readings[i]) {
      steps[waiting.back()] = i - waiting.back();
      waiting.pop_back();
    }
    waiting.push_back(i);
  }
  return steps;  // indices still waiting keep no value
}

int main() {
  const std::vector<int> readings{5, 3, 4, 8, 6, 7, 2};
  std::string_view separator;
  for (const std::optional<std::ptrdiff_t>& s : steps_to_higher(readings)) {
    std::cout << separator << (s ? std::to_string(*s) : "none");
    separator = " ";
  }
  std::cout << '\n';
}

