  std::vector<int> maxima;
  std::deque<std::ptrdiff_t> candidates;  // indices; their readings fall from front to back
  for (std::ptrdiff_t i = 0; i < std::ssize(readings); ++i) {
    // 1. drop the candidates at the back that readings[i] makes useless
    candidates.push_back(i);
    // 2. drop the candidate at the front if it has left the window
    if (i >= k - 1) maxima.push_back(readings[candidates.front()]);
  }
  return maxima;
}

#include <cstddef>
#include <deque>
#include <iostream>
#include <span>
#include <vector>

[[nodiscard]] std::vector<int> window_maxima(std::span<const int> readings, std::ptrdiff_t k) {
  std::vector<int> maxima;
  if (k < 1) return maxima;
  std::deque<std::ptrdiff_t> candidates;
  for (std::ptrdiff_t i = 0; i < std::ssize(readings); ++i) {
    while (!candidates.empty() && readings[candidates.back()] <= readings[i]) candidates.pop_back();
    candidates.push_back(i);
    if (candidates.front() <= i - k) candidates.pop_front();
    if (i >= k - 1) maxima.push_back(readings[candidates.front()]);
  }
  return maxima;
}

int main() {
  const std::vector<int> readings{4, 2, 12, 3, 8, 1, 7};
  for (const std::ptrdiff_t k : {3, 1, 8}) {
    std::cout << "k = " << k << ':';
    for (const int m : window_maxima(readings, k)) std::cout << ' ' << m;
    std::cout << '\n';
  }
}

