#include <string>
#include <type_traits>
#include <utility>
#include <vector>

template <typename T>
class TwoStackQueue {
  static_assert(std::is_nothrow_move_constructible_v<T>, "pop returns by value, so a move must not throw");

 public:
  void push(T value) { in_.push_back(std::move(value)); }

  [[nodiscard]] std::optional<T> pop() {
    if (out_.empty()) {
      moves_ += std::ssize(in_);
      std::ranges::move(in_ | std::views::reverse, std::back_inserter(out_));  // the oldest lands at the back
      in_.clear();
    }
    if (out_.empty()) return std::nullopt;
    std::optional<T> oldest{std::move(out_.back())};
    out_.pop_back();
    return oldest;
  }

  [[nodiscard]] bool empty() const { return in_.empty() && out_.empty(); }
  [[nodiscard]] std::ptrdiff_t size() const { return std::ssize(in_) + std::ssize(out_); }
  [[nodiscard]] std::int64_t moves() const { return moves_; }

 private:
  std::vector<T> in_;   // the newest element at the back
  std::vector<T> out_;  // the oldest element at the back
  std::int64_t moves_ = 0;
};

int main() {
  TwoStackQueue<std::string> commands;
  commands.push("dock");
  commands.push("charge");
  std::cout << commands.pop().value_or("none");
  commands.push("undock");
  for (int i = 0; i < 3; ++i) std::cout << ' ' << commands.pop().value_or("none");
  std::cout << '\n';

  TwoStackQueue<int> queue;
  for (int i = 0; i < 1000; ++i) queue.push(i);
  const std::optional<int> first = queue.pop();
  const std::int64_t moves_in_first_pop = queue.moves();
  bool in_order = first == 0;
  for (int i = 1; i < 1000; ++i) in_order = in_order && queue.pop() == i;
  std::cout << std::format("in order: {}, moves: {} in total, {} in the first pop, empty: {}\n", in_order,
                           queue.moves(), moves_in_first_pop, queue.empty());
}

#include <algorithm>
#include <iostream>
#include <optional>
#include <string>
#include <vector>

class MinStack {
 public:
  void push(int x) {
    const int smallest = entries_.empty() ? x : std::min(x, entries_.back().min);
    entries_.push_back({.value = x, .min = smallest});
  }

  std::optional<int> pop() {
    if (entries_.empty()) return std::nullopt;
    const int value = entries_.back().value;
    entries_.pop_back();
    return value;
  }

  [[nodiscard]] std::optional<int> top() const {
    return entries_.empty() ? std::nullopt : std::optional<int>{entries_.back().value};
  }

  [[nodiscard]] std::optional<int> min() const {
    return entries_.empty() ? std::nullopt : std::optional<int>{entries_.back().min};
  }

 private:
  struct Entry {
    int value;
    int min;  // the smallest value in this entry and every entry below it
  };
  std::vector<Entry> entries_;
};

[[nodiscard]] std::string show(const std::optional<int>& x) {
  return x ? std::to_string(*x) : "none";
}

int main() {
  MinStack stack;
  for (const int x : {5, 3, 3, 7}) stack.push(x);
  std::cout << "min " << show(stack.min()) << ", top " << show(stack.top()) << '\n';
  for (int i = 0; i < 5; ++i) {
    const std::optional<int> popped = stack.pop();
    std::cout << "popped " << show(popped) << ", min " << show(stack.min()) << '\n';
  }
}

#include <charconv>
#include <cstdint>
#include <iostream>
#include <optional>
#include <span>
#include <string>
#include <string_view>
#include <system_error>
#include <vector>

[[nodiscard]] std::optional<std::int64_t> parse_integer(std::string_view token) {
  std::int64_t value = 0;
  const char* const last = token.data() + token.size();
  const std::from_chars_result parsed = std::from_chars(token.data(), last, value);
  if (parsed.ec != std::errc{} || parsed.ptr != last) return std::nullopt;  // not a number, or trailing characters
  return value;
}

[[nodiscard]] std::optional<std::int64_t> apply_operator(char op, std::int64_t lhs, std::int64_t rhs) {
  switch (op) {
    case '+': return lhs + rhs;
    case '-': return lhs - rhs;
    case '*': return lhs * rhs;
    case '/': return rhs == 0 ? std::nullopt : std::optional<std::int64_t>{lhs / rhs};
    default: return std::nullopt;
  }
}

[[nodiscard]] std::optional<std::int64_t> evaluate_rpn(std::span<const std::string_view> tokens) {
  std::vector<std::int64_t> operands;
  for (const std::string_view token : tokens) {
    if (token == "+" || token == "-" || token == "*" || token == "/") {
      if (std::ssize(operands) < 2) return std::nullopt;
      const std::int64_t rhs = operands.back();  // the top is the right-hand operand
      operands.pop_back();
      const std::int64_t lhs = operands.back();
      operands.pop_back();
      const std::optional<std::int64_t> result = apply_operator(token.front(), lhs, rhs);
      if (!result) return std::nullopt;
      operands.push_back(*result);
    } else if (const std::optional<std::int64_t> value = parse_integer(token)) {
      operands.push_back(*value);
    } else {
      return std::nullopt;
    }
  }
  if (operands.size() != 1) return std::nullopt;
  return operands.back();
}

int main() {
  const std::vector<std::vector<std::string_view>> cases{
      {"2", "1", "+", "3", "*"}, {"4", "13", "5", "/", "+"}, {"-7", "2", "/"}, {"1", "+"},
      {"1", "0", "/"},           {"1", "2"},                 {"2", "x", "+"}, {}};
  for (const std::vector<std::string_view>& tokens : cases) {
    std::string line;
    for (const std::string_view token : tokens) line.append(token).append(" ");
    if (line.empty()) line = "(empty) ";
    const std::optional<std::int64_t> value = evaluate_rpn(tokens);
    std::cout << line << "= " << (value ? std::to_string(*value) : "no value") << '\n';
  }
}

